" height=\"26\" fill=\"#222\" opacity=\".85\"/><rect x=\"24\" y=\"56\" width=\"7\" height=\"26\" fill=\"#222\" opacity=\".85\"/><rect x=\"38\" y=\"56\" width=\"7\" height=\"26\" fill=\"#222\" opacity=\".85\"/><rect x=\"52\" y=\"56\" width=\"7\" height=\"26\" fill=\"#222\" opacity=\".85\"/><rect x=\"66\" y=\"56\" width=\"7\" height=\"26\" fill=\"#222\" opacity=\".85\"/><rect x=\"34\" y=\"50\" width=\"12\" height=\"9\" fill=\"#c68a5e\"/><ellipse cx=\"40\" cy=\"36\" rx=\"19\" ry=\"20\" fill=\"#c68a5e\"/><path d=\"M20 36 L22 16 L30 28 L36 10 L42 28 L50 12 L54 28 L60 18 L60 36 Z\" fill=\"#222\"/><ellipse cx=\"33\" cy=\"38\" rx=\"4.6\" ry=\"5.4\" fill=\"#fff\"/><ellipse cx=\"47\" cy=\"38\" rx=\"4.6\" ry=\"5.4\" fill=\"#fff\"/><circle cx=\"34\" cy=\"39\" r=\"2.5\" fill=\"#222\"/><circle cx=\"48\" cy=\"39\" r=\"2.5\" fill=\"#222\"/><path d=\"M33 47 Q40 54 47 47\" fill=\"none\" stroke=\"#222\" stroke-width=\"2.4\" stroke-linecap=\"round\"/><\/g><\/svg><div class=\"row\" style=\"gap:2px\"><div class=\"pc back xs\"><\/div><div class=\"pc back xs\"><\/div><div class=\"pc back xs\"><\/div><div class=\"pc back xs\"><\/div><div class=\"pc back xs\"><\/div><\/div><\/div><div style=\"display:grid;gap:3px;justify-items:center\"><svg class=\"av\" width=\"32\" height=\"32\" viewBox=\"0 0 80 80\"><defs><clipPath id=\"av12\"><circle cx=\"40\" cy=\"40\" r=\"40\"/><\/clipPath><\/defs><g clip-path=\"url(#av12)\"><rect width=\"80\" height=\"80\" fill=\"#1fa38a\"/><path d=\"M6 84 Q8 58 40 56 Q72 58 74 84 Z\" fill=\"#fff\"/><rect x=\"10\" y=\"56\" width=\"7\" height=\"26\" fill=\"#222\" opacity=\".85\"/><rect x=\"24\" y=\"56\" width=\"7\" height=\"26\" fill=\"#222\" opacity=\".85\"/><rect x=\"38\" y=\"56\" width=\"7\" height=\"26\" fill=\"#222\" opacity=\".85\"/><rect x=\"52\" y=\"56\" width=\"7\" height=\"26\" fill=\"#222\" opacity=\".85\"/><rect x=\"66\" y=\"56\" width=\"7\" height=\"26\" fill=\"#222\" opacity=\".85\"/><rect x=\"34\" y=\"50\" width=\"12\" height=\"9\" fill=\"#8d5a3c\"/><ellipse cx=\"40\" cy=\"36\" rx=\"19\" ry=\"20\" fill=\"#8d5a3c\"/><ellipse cx=\"32\" cy=\"24\" rx=\"5\" ry=\"3\" fill=\"#fff\" opacity=\".45\" transform=\"rotate(-30 32 24)\"/><ellipse cx=\"33\" cy=\"38\" rx=\"4.6\" ry=\"5.4\" fill=\"#fff\"/><ellipse cx=\"47\" cy=\"38\" rx=\"4.6\" ry=\"5.4\" fill=\"#fff\"/><circle cx=\"34\" cy=\"39\" r=\"2.5\" fill=\"#222\"/><circle cx=\"48\" cy=\"39\" r=\"2.5\" fill=\"#222\"/><path d=\"M33 47 Q40 54 47 47\" fill=\"none\" stroke=\"#222\" stroke-width=\"2.4\" stroke-linecap=\"round\"/><\/g><\/svg><div class=\"row\" style=\"gap:2px\"><div class=\"pc back xs\"><\/div><div class=\"pc back xs\"><\/div><div class=\"pc back xs\"><\/div><div class=\"pc back xs\"><\/div><div class=\"pc back xs\"><\/div><\/div><\/div><div style=\"display:grid;gap:3px;justify-items:center\"><svg class=\"av\" width=\"32\" height=\"32\" viewBox=\"0 0 80 80\"><defs><clipPath id=\"av13\"><circle cx=\"40\" cy=\"40\" r=\"40\"/><\/clipPath><\/defs><g clip-path=\"url(#av13)\"><rect width=\"80\" height=\"80\" fill=\"#7a4fd1\"/><path d=\"M6 84 Q8 58 40 56 Q72 58 74 84 Z\" fill=\"#fff\"/><rect x=\"10\" y=\"56\" width=\"7\" height=\"26\" fill=\"#222\" opacity=\".85\"/><rect x=\"24\" y=\"56\" width=\"7\" height=\"26\" fill=\"#222\" opacity=\".85\"/><rect x=\"38\" y=\"56\" width=\"7\" height=\"26\" fill=\"#222\" opacity=\".85\"/><rect x=\"52\" y=\"56\" width=\"7\" height=\"26\" fill=\"#222\" opacity=\".85\"/><rect x=\"66\" y=\"56\" width=\"7\" height=\"26\" fill=\"#222\" opacity=\".85\"/><rect x=\"34\" y=\"50\" width=\"12\" height=\"9\" fill=\"#f6d3b3\"/><ellipse cx=\"40\" cy=\"36\" rx=\"19\" ry=\"20\" fill=\"#f6d3b3\"/><path d=\"M22 30 L22 14 L31 22 L40 10 L49 22 L58 14 L58 30 Z\" fill=\"#f7c928\" stroke=\"#c99a00\" stroke-width=\"2\" stroke-linejoin=\"round\"/><rect x=\"22\" y=\"28\" width=\"36\" height=\"5\" fill=\"#f7c928\" stroke=\"#c99a00\" stroke-width=\"2\"/><ellipse cx=\"33\" cy=\"38\" rx=\"4.6\" ry=\"5.4\" fill=\"#fff\"/><ellipse cx=\"47\" cy=\"38\" rx=\"4.6\" ry=\"5.4\" fill=\"#fff\"/><circle cx=\"34\" cy=\"39\" r=\"2.5\" fill=\"#222\"/><circle cx=\"48\" cy=\"39\" r=\"2.5\" fill=\"#222\"/><path d=\"M33 47 Q40 54 47 47\" fill=\"none\" stroke=\"#222\" stroke-width=\"2.4\" stroke-linecap=\"round\"/><\/g><\/svg><div class=\"row\" style=\"gap:2px\"><div class=\"pc back xs\"><\/div><div class=\"pc back xs\"><\/div><div class=\"pc back xs\"><\/div><div class=\"pc back xs\"><\/div><div class=\"pc back xs\"><\/div><\/div><\/div><\/div>\n  <div class=\"cap\">Each inmate holds five cards. The backs shown here face the player; everyone else sees the fronts.<\/div><\/div>\n <div class=\"box\"><h3>The big twist: you can’t see your own hand<\/h3>\n  <div class=\"row\" style=\"gap:30px\">\n   <div style=\"display:grid;gap:4px;justify-items:center\"><div class=\"lab\">What your crew sees<\/div><div class=\"row\" style=\"gap:3px\"><div class=\"pc red sm\"><span class=\"r\">7<\/span><span class=\"s\">♥<\/span><span class=\"big\">♥<\/span><\/div><div class=\"pc sm\"><span class=\"r\">A<\/span><span class=\"s\">♠<\/span><span class=\"big\">♠<\/span><\/div><div class=\"pc red sm\"><span class=\"r\">Q<\/span><span class=\"s\">♦<\/span><span class=\"big\">♦<\/span><\/div><div class=\"pc sm\"><span class=\"r\">4<\/span><span class=\"s\">♣<\/span><span class=\"big\">♣<\/span><\/div><div class=\"pc sm\"><span class=\"r\">9<\/span><span class=\"s\">♠<\/span><span class=\"big\">♠<\/span><\/div><\/div><\/div>\n   <div style=\"font-size:22pt\">↔<\/div>\n   <div style=\"display:grid;gap:4px;justify-items:center\"><div class=\"lab\">What you see<\/div><div class=\"row\" style=\"gap:3px\"><div class=\"pc back sm\"><\/div><div class=\"pc back sm\"><\/div><div class=\"pc back sm\"><\/div><div class=\"pc back sm\"><\/div><div class=\"pc back sm\"><\/div><\/div><\/div>\n  <\/div>\n  <p class=\"cap\" style=\"text-align:center;margin-top:4px;color:var(--muted);font-size:8.5pt\">Your teammates give you hints (a suit or a rank) through Guard Checks. Keep track of what you’ve been told.<\/p><\/div>\n <div class=\"foot\"><span>Escape from Ace-catraz · Rules<\/span><span>2<\/span><\/div><\/div><div class=\"page\"><div class=\"hd\"><div class=\"n\">2<\/div><h2>On your turn<\/h2><small>Choose one action, then optionally Breakthrough<\/small><\/div>\n <div class=\"row\" style=\"gap:10px\"><div class=\"box\" style=\"flex:1;text-align:center\"><b>1.<\/b> Perform <b>one<\/b> of the five actions<\/div><div class=\"arrow\">›<\/div><div class=\"box\" style=\"flex:1;text-align:center\"><b>2.<\/b> Optionally attempt a <b>Breakthrough<\/b><\/div><\/div>\n <div class=\"action\"><h4><span>1<\/span>Play my part<\/h4>\n  <div class=\"row\" style=\"justify-content:space-between;gap:14px;align-items:center\">\n   <div><ol style=\"padding-left:16px\"><li>Choose a card from your hand <b>without looking at it<\/b>. Place it face down on an <b>unoccupied corner of the active Obstacle<\/b>.<\/li><li>Draw a card from the Flashlight Deck into your hand. Keep it facing away from you.<\/li><\/ol><\/div>\n   <div class=\"row\" style=\"gap:6px\"><div class=\"sc up s\"><i>ESCAPE PLAN<\/i><b>RED<\/b><em>MATCH<\/em><span>HEARTS ♥ OR DIAMONDS ♦<\/span><u class=\"easy\">EASY<\/u><\/div><div style=\"display:grid;grid-template-columns:auto auto;gap:4px\"><div class=\"pc back sm\"><\/div><div class=\"pc back sm\"><\/div><div class=\"pc sm\" style=\"border:2px dashed #aab;background:transparent;box-shadow:none\"><\/div><div class=\"pc sm\" style=\"border:2px dashed #aab;background:transparent;box-shadow:none\"><\/div><\/div><\/div>\n  <\/div><\/div>\n <div class=\"action\"><h4><span>2<\/span>Perform a Guard check<\/h4>\n  <div class=\"row\" style=\"justify-content:space-between;gap:14px\">\n   <div><ol style=\"padding-left:16px\"><li>Flip the top <b>Patrol<\/b> card and the top <b>Flashlight<\/b> card.<\/li><li>Compare the Flashlight card against the Patrol card’s criteria.<ul><li><b class=\"bad\">Fail:<\/b> the card <i>matches<\/i> the “DO NOT MATCH” line. Stay silent. Your turn is over.<\/li><li><b class=\"ok\">Pass:<\/b> the card does <i>not<\/i> match. Point to a card in a teammate’s hand and say either its <b>suit<\/b> or its <b>rank<\/b>.<\/li><\/ul><\/li><li>Discard both revealed cards.<\/li><\/ol><\/div>\n  <\/div>\n  <div class=\"cols c2\" style=\"margin-top:8px\">\n   <div class=\"diag\" style=\"background:#f3f6fa;padding:8px\"><div class=\"row\" style=\"gap:8px\"><div class=\"sc pat easy s\"><i>GUARD CHECK<\/i><b>EXTREME CAUTION<\/b><em>DO NOT MATCH<\/em><span>HEARTS ♥ OR DIAMONDS ♦<\/span><\/div><span class=\"lab\">vs<\/span><div class=\"pc \"><span class=\"r\">7<\/span><span class=\"s\">♠<\/span><span class=\"big\">♠<\/span><\/div><div style=\"font-weight:900;font-size:9.5pt\" class=\"ok\">PASS ✓<br><span style=\"font-weight:600;color:var(--ink)\">7♠ is not red.<br>Give a hint!<\/span><\/div><\/div><\/div>\n   <div class=\"diag\" style=\"background:#f3f6fa;padding:8px\"><div class=\"row\" style=\"gap:8px\"><div class=\"sc pat easy s\"><i>GUARD CHECK<\/i><b>EXTREME CAUTION<\/b><em>DO NOT MATCH<\/em><span>HEARTS ♥ OR DIAMONDS ♦<\/span><\/div><span class=\"lab\">vs<\/span><div class=\"pc red \"><span class=\"r\">Q<\/span><span class=\"s\">♥<\/span><span class=\"big\">♥<\/span><\/div><div style=\"font-weight:900;font-size:9.5pt\" class=\"bad\">FAIL ✗<br><span style=\"font-weight:600;color:var(--ink)\">Q♥ is red.<br>Say nothing.<\/span><\/div><\/div><\/div>\n  <\/div>\n  <div class=\"call warn\" style=\"margin-top:8px\"><b>Reading the Patrol card:<\/b> the card’s coloured label tells you how risky the check is. <b>Extreme caution<\/b> (the card’s obstacle side is Easy) is hard to pass because it forbids half the deck. <b>Relaxed<\/b> (the card’s obstacle side is Hard) is easy to pass because it only forbids a couple of ranks. The top of the Patrol deck always shows how tough the next check is.<\/div>\n <\/div>\n <div class=\"box\" style=\"padding:8px 14px\"><h3>Hints, in practice<\/h3><div class=\"row\" style=\"gap:16px\"><div style=\"display:grid;gap:4px;justify-items:center\"><svg class=\"av\" width=\"36\" height=\"36\" viewBox=\"0 0 80 80\"><defs><clipPath id=\"av14\"><circle cx=\"40\" cy=\"40\" r=\"40\"/><\/clipPath><\/defs><g clip-path=\"url(#av14)\"><rect width=\"80\" height=\"80\" fill=\"#e23d4a\"/><path d=\"M6 84 Q8 58 40 56 Q72 58 74 84 Z\" fill=\"#fff\"/><rect x=\"10\" y=\"56\" width=\"7\" height=\"26\" fill=\"#222\" opacity=\".85\"/><rect x=\"24\" y=\"56\" width=\"7\" height=\"26\" fill=\"#222\" opacity=\".85\"/><rect x=\"38\" y=\"56\" width=\"7\" height=\"26\" fill=\"#222\" opacity=\".85\"/><rect x=\"52\" y=\"56\" width=\"7\" height=\"26\" fill=\"#222\" opacity=\".85\"/><rect x=\"66\" y=\"56\" width=\"7\" height=\"26\" fill=\"#222\" opacity=\".85\"/><rect x=\"34\" y=\"50\" width=\"12\" height=\"9\" fill=\"#c68a5e\"/><ellipse cx=\"40\" cy=\"36\" rx=\"19\" ry=\"20\" fill=\"#c68a5e\"/><path d=\"M20 36 L22 16 L30 28 L36 10 L42 28 L50 12 L54 28 L60 18 L60 36 Z\" fill=\"#222\"/><ellipse cx=\"33\" cy=\"38\" rx=\"4.6\" ry=\"5.4\" fill=\"#fff\"/><ellipse cx=\"47\" cy=\"38\" rx=\"4.6\" ry=\"5.4\" fill=\"#fff\"/><circle cx=\"34\" cy=\"39\" r=\"2.5\" fill=\"#222\"/><circle cx=\"48\" cy=\"39\" r=\"2.5\" fill=\"#222\"/><path d=\"M33 47 Q40 54 47 47\" fill=\"none\" stroke=\"#222\" stroke-width=\"2.4\" stroke-linecap=\"round\"/><\/g><\/svg><div class=\"row\" style=\"gap:3px\"><div class=\"pc red sm\"><span class=\"r\">7<\/span><span class=\"s\">♥<\/span><span class=\"big\">♥<\/span><\/div><div class=\"pc sm hit\"><span class=\"r\">3<\/span><span class=\"s\">♣<\/span><span class=\"big\">♣<\/span><\/div><div class=\"pc sm\"><span class=\"r\">10<\/span><span class=\"s\">♠<\/span><span class=\"big\">♠<\/span><\/div><\/div><\/div><div style=\"font-size:9.6pt;max-width:330px\">“<b>That one is a club<\/b>” <span style=\"color:var(--muted)\">(pointing at the 3♣)<\/span> or “<b>that one is a 3<\/b>”. Say a suit <i>or<\/i> a rank, never both. Your teammate remembers it and builds the picture over several turns.<\/div><\/div><\/div>\n <div class=\"foot\"><span>Escape from Ace-catraz · Rules<\/span><span>3<\/span><\/div><\/div><div class=\"page\"><div class=\"hd\"><div class=\"n\">2<\/div><h2>On your turn, continued<\/h2><small>Actions 3 to 5 and the Breakthrough<\/small><\/div>\n <div class=\"action\"><h4><span>3<\/span>Distract<\/h4><p>Discard <b>any<\/b> card at the active Obstacle, then choose a Patrol card from the discard pile and shuffle it back into the Patrol deck. Use it to remove a card you know is wrong, and to bring back an easy Guard Check.<\/p><\/div>\n <div class=\"action\"><h4><span>4<\/span>Riot<\/h4><p>Discard <b>5 cards<\/b> from the top of the Flashlight Deck (the deck must have at least 5 cards left), then <b>swap any two cards<\/b>: your own, another player’s, or one from the discard pile. At least one has to be in a player’s hand. Riots are the best way to move a card to where it’s needed.<\/p><\/div>\n <div class=\"action\"><h4><span>5<\/span>Pass<\/h4><p>Only available once the <b>Alarm Sounds card is visible<\/b>, which means the Flashlight Deck has run out. Skip your turn. (Pass is also what you do if you have no other legal action.)<\/p>\n  <div class=\"row\" style=\"justify-content:flex-start;gap:12px;margin-top:4px\"><div class=\"sc alarm s\"><i>ALARM SOUNDS<\/i><b>🚨<\/b><span>Drawing LOCKED. Pass allowed.<\/span><\/div><div style=\"font-size:9.2pt\">When the Alarm card is revealed, <b>drawing is locked<\/b>. Planting a card no longer replaces it, so your hands shrink as the crew plants.<\/div><\/div><\/div>\n <div class=\"hd\" style=\"margin:4px -0.55in 0\"><div class=\"n\">3<\/div><h2>Breakthrough<\/h2><small>Optional, at the end of your turn<\/small><\/div>\n <div class=\"box\"><p>If <b>each player has planted exactly one card<\/b> on the active Obstacle, you may attempt a Breakthrough.<\/p><ol style=\"margin-top:4px\"><li>Reveal every card planted at the active Obstacle.<\/li><li><b class=\"ok\">All cards meet the condition →<\/b> success! Stack the used cards face down on the Obstacle, reveal the next face-down Obstacle (so two are visible), and the next Obstacle in your direction becomes active.<\/li><li><b class=\"bad\">Even one card fails →<\/b> the alarm is tripped and <b>everyone loses immediately<\/b>.<\/li><\/ol><\/div>\n <div class=\"cols c2\">\n  <div class=\"diag\" style=\"border:3px solid #19b57a\"><div class=\"lab ok\">Success · 3 players · obstacle: RED<\/div><div class=\"row\" style=\"gap:6px\"><div class=\"sc up s\"><i>ESCAPE PLAN<\/i><b>RED<\/b><em>MATCH<\/em><span>HEARTS ♥ OR DIAMONDS ♦<\/span><u class=\"easy\">EASY<\/u><\/div><span class=\"arrow\">›<\/span><div class=\"pc red sm hit\"><span class=\"r\">4<\/span><span class=\"s\">♥<\/span><span class=\"big\">♥<\/span><\/div><div class=\"pc red sm hit\"><span class=\"r\">J<\/span><span class=\"s\">♦<\/span><span class=\"big\">♦<\/span><\/div><div class=\"pc red sm hit\"><span class=\"r\">9<\/span><span class=\"s\">♥<\/span><span class=\"big\">♥<\/span><\/div><\/div><div class=\"cap\">All three are red. On to the next Obstacle!<\/div><\/div>\n  <div class=\"diag\" style=\"border:3px solid var(--red)\"><div class=\"lab bad\">Alarm! · 3 players · obstacle: RED<\/div><div class=\"row\" style=\"gap:6px\"><div class=\"sc up s\"><i>ESCAPE PLAN<\/i><b>RED<\/b><em>MATCH<\/em><span>HEARTS ♥ OR DIAMONDS ♦<\/span><u class=\"easy\">EASY<\/u><\/div><span class=\"arrow\" style=\"color:var(--red)\">›<\/span><div class=\"pc red sm hit\"><span class=\"r\">4<\/span><span class=\"s\">♥<\/span><span class=\"big\">♥<\/span><\/div><div class=\"pc sm miss\"><span class=\"r\">6<\/span><span class=\"s\">♠<\/span><span class=\"big\">♠<\/span><\/div><div class=\"pc red sm hit\"><span class=\"r\">9<\/span><span class=\"s\">♥<\/span><span class=\"big\">♥<\/span><\/div><\/div><div class=\"cap\">The 6♠ is black. Everyone loses.<\/div><\/div>\n <\/div>\n <div class=\"call good\"><b>Safety first.<\/b> Before attempting, make sure every planted card is one you’re certain about. If any player is unsure of their own planted card, it’s often smarter to let a teammate who <i>is<\/i> certain make the call, or to Distract it. If one planted card is certain to be right, <b>one verifier<\/b> is enough: everyone else’s planted cards were seen while being planted.<\/div>\n <div class=\"foot\"><span>Escape from Ace-catraz · Rules<\/span><span>4<\/span><\/div><\/div><div class=\"page\"><div class=\"hd\"><div class=\"n\">4<\/div><h2>End game<\/h2><small>Win, lose, and reminders<\/small><\/div>\n <div class=\"cols c2\">\n  <div class=\"call good\" style=\"display:grid;gap:5px;justify-items:center;text-align:center\"><div style=\"font-size:20pt;font-weight:900;color:var(--green)\">FREEDOM!<\/div><div class=\"crew\" style=\"gap:6px\"><svg class=\"av\" width=\"38\" height=\"38\" viewBox=\"0 0 80 80\"><defs><clipPath id=\"av15\"><circle cx=\"40\" cy=\"40\" r=\"40\"/><\/clipPath><\/defs><g clip-path=\"url(#av15)\"><rect width=\"80\" height=\"80\" fill=\"#f2a516\"/><path d=\"M6 84 Q8 58 40 56 Q72 58 74 84 Z\" fill=\"#fff\"/><rect x=\"10\" y=\"56\" width=\"7\" height=\"26\" fill=\"#222\" opacity=\".85\"/><rect x=\"24\" y=\"56\" width=\"7\" height=\"26\" fill=\"#222\" opacity=\".85\"/><rect x=\"38\" y=\"56\" width=\"7\" height=\"26\" fill=\"#222\" opacity=\".85\"/><rect x=\"52\" y=\"56\" width=\"7\" height=\"26\" fill=\"#222\" opacity=\".85\"/><rect x=\"66\" y=\"56\" width=\"7\" height=\"26\" fill=\"#222\" opacity=\".85\"/><rect x=\"34\" y=\"50\" width=\"12\" height=\"9\" fill=\"#f6c9a0\"/><ellipse cx=\"40\" cy=\"36\" rx=\"19\" ry=\"20\" fill=\"#f6c9a0\"/><path d=\"M20 36 Q20 14 40 14 Q60 14 60 36 Z\" fill=\"#e23d4a\"/><rect x=\"18\" y=\"32\" width=\"44\" height=\"8\" rx=\"4\" fill=\"#fff\"/><circle cx=\"40\" cy=\"12\" r=\"4\" fill=\"#fff\"/><ellipse cx=\"33\" cy=\"38\" rx=\"4.6\" ry=\"5.4\" fill=\"#fff\"/><ellipse cx=\"47\" cy=\"38\" rx=\"4.6\" ry=\"5.4\" fill=\"#fff\"/><circle cx=\"34\" cy=\"39\" r=\"2.5\" fill=\"#222\"/><circle cx=\"48\" cy=\"39\" r=\"2.5\" fill=\"#222\"/><path d=\"M33 47 Q40 54 47 47\" fill=\"none\" stroke=\"#222\" stroke-width=\"2.4\" stroke-linecap=\"round\"/><\/g><\/svg><svg class=\"av\" width=\"38\" height=\"38\" viewBox=\"0 0 80 80\"><defs><clipPath id=\"av16\"><circle cx=\"40\" cy=\"40\" r=\"40\"/><\/clipPath><\/defs><g clip-path=\"url(#av16)\"><rect width=\"80\" height=\"80\" fill=\"#e23d4a\"/><path d=\"M6 84 Q8 58 40 56 Q72 58 74 84 Z\" fill=\"#fff\"/><rect x=\"10\" y=\"56\" width=\"7\" height=\"26\" fill=\"#222\" opacity=\".85\"/><rect x=\"24\" y=\"56\" width=\"7\" height=\"26\" fill=\"#222\" opacity=\".85\"/><rect x=\"38\" y=\"56\" width=\"7\" height=\"26\" fill=\"#222\" opacity=\".85\"/><rect x=\"52\" y=\"56\" width=\"7\" height=\"26\" fill=\"#222\" opacity=\".85\"/><rect x=\"66\" y=\"56\" width=\"7\" height=\"26\" fill=\"#222\" opacity=\".85\"/><rect x=\"34\" y=\"50\" width=\"12\" height=\"9\" fill=\"#c68a5e\"/><ellipse cx=\"40\" cy=\"36\" rx=\"19\" ry=\"20\" fill=\"#c68a5e\"/><path d=\"M20 36 L22 16 L30 28 L36 10 L42 28 L50 12 L54 28 L60 18 L60 36 Z\" fill=\"#222\"/><ellipse cx=\"33\" cy=\"38\" rx=\"4.6\" ry=\"5.4\" fill=\"#fff\"/><ellipse cx=\"47\" cy=\"38\" rx=\"4.6\" ry=\"5.4\" fill=\"#fff\"/><circle cx=\"34\" cy=\"39\" r=\"2.5\" fill=\"#222\"/><circle cx=\"48\" cy=\"39\" r=\"2.5\" fill=\"#222\"/><path d=\"M33 47 Q40 54 47 47\" fill=\"none\" stroke=\"#222\" stroke-width=\"2.4\" stroke-linecap=\"round\"/><\/g><\/svg><svg class=\"av\" width=\"38\" height=\"38\" viewBox=\"0 0 80 80\"><defs><clipPath id=\"av17\"><circle cx=\"40\" cy=\"40\" r=\"40\"/><\/clipPath><\/defs><g clip-path=\"url(#av17)\"><rect width=\"80\" height=\"80\" fill=\"#1fa38a\"/><path d=\"M6 84 Q8 58 40 56 Q72 58 74 84 Z\" fill=\"#fff\"/><rect x=\"10\" y=\"56\" width=\"7\" height=\"26\" fill=\"#222\" opacity=\".85\"/><rect x=\"24\" y=\"56\" width=\"7\" height=\"26\" fill=\"#222\" opacity=\".85\"/><rect x=\"38\" y=\"56\" width=\"7\" height=\"26\" fill=\"#222\" opacity=\".85\"/><rect x=\"52\" y=\"56\" width=\"7\" height=\"26\" fill=\"#222\" opacity=\".85\"/><rect x=\"66\" y=\"56\" width=\"7\" height=\"26\" fill=\"#222\" opacity=\".85\"/><rect x=\"34\" y=\"50\" width=\"12\" height=\"9\" fill=\"#8d5a3c\"/><ellipse cx=\"40\" cy=\"36\" rx=\"19\" ry=\"20\" fill=\"#8d5a3c\"/><ellipse cx=\"32\" cy=\"24\" rx=\"5\" ry=\"3\" fill=\"#fff\" opacity=\".45\" transform=\"rotate(-30 32 24)\"/><ellipse cx=\"33\" cy=\"38\" rx=\"4.6\" ry=\"5.4\" fill=\"#fff\"/><ellipse cx=\"47\" cy=\"38\" rx=\"4.6\" ry=\"5.4\" fill=\"#fff\"/><circle cx=\"34\" cy=\"39\" r=\"2.5\" fill=\"#222\"/><circle cx=\"48\" cy=\"39\" r=\"2.5\" fill=\"#222\"/><path d=\"M33 47 Q40 54 47 47\" fill=\"none\" stroke=\"#222\" stroke-width=\"2.4\" stroke-linecap=\"round\"/><\/g><\/svg><svg class=\"av\" width=\"38\" height=\"38\" viewBox=\"0 0 80 80\"><defs><clipPath id=\"av18\"><circle cx=\"40\" cy=\"40\" r=\"40\"/><\/clipPath><\/defs><g clip-path=\"url(#av18)\"><rect width=\"80\" height=\"80\" fill=\"#7a4fd1\"/><path d=\"M6 84 Q8 58 40 56 Q72 58 74 84 Z\" fill=\"#fff\"/><rect x=\"10\" y=\"56\" width=\"7\" height=\"26\" fill=\"#222\" opacity=\".85\"/><rect x=\"24\" y=\"56\" width=\"7\" height=\"26\" fill=\"#222\" opacity=\".85\"/><rect x=\"38\" y=\"56\" width=\"7\" height=\"26\" fill=\"#222\" opacity=\".85\"/><rect x=\"52\" y=\"56\" width=\"7\" height=\"26\" fill=\"#222\" opacity=\".85\"/><rect x=\"66\" y=\"56\" width=\"7\" height=\"26\" fill=\"#222\" opacity=\".85\"/><rect x=\"34\" y=\"50\" width=\"12\" height=\"9\" fill=\"#f6d3b3\"/><ellipse cx=\"40\" cy=\"36\" rx=\"19\" ry=\"20\" fill=\"#f6d3b3\"/><path d=\"M22 30 L22 14 L31 22 L40 10 L49 22 L58 14 L58 30 Z\" fill=\"#f7c928\" stroke=\"#c99a00\" stroke-width=\"2\" stroke-linejoin=\"round\"/><rect x=\"22\" y=\"28\" width=\"36\" height=\"5\" fill=\"#f7c928\" stroke=\"#c99a00\" stroke-width=\"2\"/><ellipse cx=\"33\" cy=\"38\" rx=\"4.6\" ry=\"5.4\" fill=\"#fff\"/><ellipse cx=\"47\" cy=\"38\" rx=\"4.6\" ry=\"5.4\" fill=\"#fff\"/><circle cx=\"34\" cy=\"39\" r=\"2.5\" fill=\"#222\"/><circle cx=\"48\" cy=\"39\" r=\"2.5\" fill=\"#222\"/><path d=\"M33 47 Q40 54 47 47\" fill=\"none\" stroke=\"#222\" stroke-width=\"2.4\" stroke-linecap=\"round\"/><\/g><\/svg><\/div><div>If you have completed <b>all Obstacles<\/b> in the Escape Plan, you win. Enjoy your freedom!<\/div><\/div>\n  <div class=\"call bad\" style=\"display:grid;gap:5px;justify-items:center;text-align:center\"><div style=\"font-size:20pt;font-weight:900;color:var(--red)\">BACK TO YOUR CELLS<\/div><div style=\"font-size:26pt;line-height:1\">🚨<\/div><div>If any <b>Breakthrough fails<\/b>, or <b>all players have no cards in hand<\/b> and Obstacles remain, you lose.<\/div><\/div>\n <\/div>\n <div class=\"box\"><h3>Critical reminders<\/h3><ul>\n  <li>You see your teammates’ hands; <b>you cannot see your own<\/b>.<\/li>\n  <li>Once a card is planted face down, <b>no one can look at it again<\/b>.<\/li>\n  <li>Inmates can only ever see the <b>active Obstacle and the next one<\/b> on the Escape Plan.<\/li>\n  <li>You may only plant cards at the <b>active Obstacle<\/b>.<\/li>\n  <li>Every Obstacle must have <b>exactly one card from each player<\/b> to pass it.<\/li>\n  <li>If any deck is empty, you <b>cannot reshuffle<\/b>.<\/li><\/ul><\/div>\n <div class=\"box\"><h3>Quick reference: your five actions<\/h3><table>\n  <tr><th>Action<\/th><th>What it does<\/th><th>When it shines<\/th><\/tr>\n  <tr><td><b>Play my part<\/b><\/td><td>Plant a blind card face down, then draw<\/td><td>You know your card is right, or you want to cycle in a fresh one<\/td><\/tr>\n  <tr><td><b>Guard check<\/b><\/td><td>Flip Patrol + Flashlight card; if you pass, give a hint<\/td><td>The crew needs information<\/td><\/tr>\n  <tr><td><b>Distract<\/b><\/td><td>Discard a planted card; return a Patrol card to the deck<\/td><td>A planted card is wrong or suspect<\/td><\/tr>\n  <tr><td><b>Riot<\/b><\/td><td>Discard 5 from the deck, swap any two cards<\/td><td>The card an Obstacle needs is in the wrong hand<\/td><\/tr>\n  <tr><td><b>Pass<\/b><\/td><td>Do nothing<\/td><td>Alarm visible and nothing useful to do<\/td><\/tr><\/table><\/div>\n <div class=\"box\"><h3>Tips for the crew<\/h3><div class=\"cols c2\" style=\"gap:14px\"><ul>\n  <li><b>Talk in hints, not answers.<\/b> Only a suit <i>or<\/i> a rank. Never both, never “that one’s fine”.<\/li>\n  <li><b>Track what you know.<\/b> Write the hints on your fingers, or jot them in the margin of a scorepad.<\/li>\n  <li><b>Watch every plant.<\/b> You’ll need to remember every planted card to judge a Breakthrough.<\/li><\/ul><ul>\n  <li><b>Planting a mystery card can be smart.<\/b> It’s a way to bring fresh cards into your hand, because a teammate can Distract it if it’s wrong. Just don’t trigger the Breakthrough on it yourself.<\/li>\n  <li><b>Pick your direction wisely.<\/b> Tackle hard locks while the deck is full, or clear easy ones first and keep hints flowing.<\/li>\n  <li><b>Mind the Flashlight Deck.<\/b> When it runs dry, drawing stops and hands shrink.<\/li><\/ul><\/div><\/div>\n <div class=\"foot\"><span>Escape from Ace-catraz · Rules<\/span><span>5<\/span><\/div><\/div><div class=\"page\"><div class=\"hd\"><div class=\"n\">A<\/div><h2>Card reference<\/h2><small>Every Security card, both sides<\/small><\/div>\n <p style=\"font-size:9.2pt;color:var(--muted)\">Each Security card is two-sided. Its <b>obstacle<\/b> side (top row of each pair) says what must be planted; its <b>Guard Check<\/b> side (bottom row) says what to avoid. A card that’s EASY to match is EXTREME CAUTION to guard-check, and vice versa.<\/p>\n <div class=\"box\"><h3 style=\"color:#1fa38a\">Easy · 6 cards<\/h3><div class=\"grid6\"><div style=\"display:grid;gap:4px;justify-items:center\"><div class=\"sc up s\"><i>ESCAPE PLAN<\/i><b>ODD<\/b><em>MATCH<\/em><span>A, 3, 5, 7, 9, J, K<\/span><u class=\"easy\">EASY<\/u><\/div><div class=\"sc pat easy s\"><i>GUARD CHECK<\/i><b>EXTREME CAUTION<\/b><em>DO NOT MATCH<\/em><span>A, 3, 5, 7, 9, J, K<\/span><\/div><\/div><div style=\"display:grid;gap:4px;justify-items:center\"><div class=\"sc up s\"><i>ESCAPE PLAN<\/i><b>HIGH<\/b><em>MATCH<\/em><span>RANKS 7 THROUGH K<\/span><u class=\"easy\">EASY<\/u><\/div><div class=\"sc pat easy s\"><i>GUARD CHECK<\/i><b>EXTREME CAUTION<\/b><em>DO NOT MATCH<\/em><span>RANKS 7 THROUGH K<\/span><\/div><\/div><div style=\"display:grid;gap:4px;justify-items:center\"><div class=\"sc up s\"><i>ESCAPE PLAN<\/i><b>RED<\/b><em>MATCH<\/em><span>HEARTS ♥ OR DIAMONDS ♦<\/span><u class=\"easy\">EASY<\/u><\/div><div class=\"sc pat easy s\"><i>GUARD CHECK<\/i><b>EXTREME CAUTION<\/b><em>DO NOT MATCH<\/em><span>HEARTS ♥ OR DIAMONDS ♦<\/span><\/div><\/div><div style=\"display:grid;gap:4px;justify-items:center\"><div class=\"sc up s\"><i>ESCAPE PLAN<\/i><b>BLACK<\/b><em>MATCH<\/em><span>SPADES ♠ OR CLUBS ♣<\/span><u class=\"easy\">EASY<\/u><\/div><div class=\"sc pat easy s\"><i>GUARD CHECK<\/i><b>EXTREME CAUTION<\/b><em>DO NOT MATCH<\/em><span>SPADES ♠ OR CLUBS ♣<\/span><\/div><\/div><div style=\"display:grid;gap:4px;justify-items:center\"><div class=\"sc up s\"><i>ESCAPE PLAN<\/i><b>EVEN<\/b><em>MATCH<\/em><span>2, 4, 6, 8, 10, Q<\/span><u class=\"easy\">EASY<\/u><\/div><div class=\"sc pat easy s\"><i>GUARD CHECK<\/i><b>EXTREME CAUTION<\/b><em>DO NOT MATCH<\/em><span>2, 4, 6, 8, 10, Q<\/span><\/div><\/div><div style=\"display:grid;gap:4px;justify-items:center\"><div class=\"sc up s\"><i>ESCAPE PLAN<\/i><b>LOW<\/b><em>MATCH<\/em><span>RANKS A THROUGH 6<\/span><u class=\"easy\">EASY<\/u><\/div><div class=\"sc pat easy s\"><i>GUARD CHECK<\/i><b>EXTREME CAUTION<\/b><em>DO NOT MATCH<\/em><span>RANKS A THROUGH 6<\/span><\/div><\/div><\/div><\/div>\n <div class=\"box\"><h3 style=\"color:#e08a00\">Medium · 6 cards<\/h3><div class=\"grid6\"><div style=\"display:grid;gap:4px;justify-items:center\"><div class=\"sc up s\"><i>ESCAPE PLAN<\/i><b>HEART<\/b><em>MATCH<\/em><span>HEARTS ♥<\/span><u class=\"medium\">MEDIUM<\/u><\/div><div class=\"sc pat medium s\"><i>GUARD CHECK<\/i><b>MEDIUM<\/b><em>DO NOT MATCH<\/em><span>HEARTS ♥<\/span><\/div><\/div><div style=\"display:grid;gap:4px;justify-items:center\"><div class=\"sc up s\"><i>ESCAPE PLAN<\/i><b>DIAMOND<\/b><em>MATCH<\/em><span>DIAMONDS ♦<\/span><u class=\"medium\">MEDIUM<\/u><\/div><div class=\"sc pat medium s\"><i>GUARD CHECK<\/i><b>MEDIUM<\/b><em>DO NOT MATCH<\/em><span>DIAMONDS ♦<\/span><\/div><\/div><div style=\"display:grid;gap:4px;justify-items:center\"><div class=\"sc up s\"><i>ESCAPE PLAN<\/i><b>SPADE<\/b><em>MATCH<\/em><span>SPADES ♠<\/span><u class=\"medium\">MEDIUM<\/u><\/div><div class=\"sc pat medium s\"><i>GUARD CHECK<\/i><b>MEDIUM<\/b><em>DO NOT MATCH<\/em><span>SPADES ♠<\/span><\/div><\/div><div style=\"display:grid;gap:4px;justify-items:center\"><div class=\"sc up s\"><i>ESCAPE PLAN<\/i><b>CLUB<\/b><em>MATCH<\/em><span>CLUBS ♣<\/span><u class=\"medium\">MEDIUM<\/u><\/div><div class=\"sc pat medium s\"><i>GUARD CHECK<\/i><b>MEDIUM<\/b><em>DO NOT MATCH<\/em><span>CLUBS ♣<\/span><\/div><\/div><div style=\"display:grid;gap:4px;justify-items:center\"><div class=\"sc up s\"><i>ESCAPE PLAN<\/i><b>FACE<\/b><em>MATCH<\/em><span>JACK, QUEEN, OR KING<\/span><u class=\"medium\">MEDIUM<\/u><\/div><div class=\"sc pat medium s\"><i>GUARD CHECK<\/i><b>MEDIUM<\/b><em>DO NOT MATCH<\/em><span>JACK, QUEEN, OR KING<\/span><\/div><\/div><div style=\"display:grid;gap:4px;justify-items:center\"><div class=\"sc up s\"><i>ESCAPE PLAN<\/i><b>A, 2, 3<\/b><em>MATCH<\/em><span>A, 2, OR 3<\/span><u class=\"medium\">MEDIUM<\/u><\/div><div class=\"sc pat medium s\"><i>GUARD CHECK<\/i><b>MEDIUM<\/b><em>DO NOT MATCH<\/em><span>A, 2, OR 3<\/span><\/div><\/div><\/div><\/div>\n <div class=\"box\"><h3 style=\"color:#d23b4a\">Hard · 5 cards<\/h3><div class=\"grid6\"><div style=\"display:grid;gap:4px;justify-items:center\"><div class=\"sc up s\"><i>ESCAPE PLAN<\/i><b>Q, K<\/b><em>MATCH<\/em><span>QUEEN OR KING<\/span><u class=\"hard\">HARD<\/u><\/div><div class=\"sc pat hard s\"><i>GUARD CHECK<\/i><b>RELAXED<\/b><em>DO NOT MATCH<\/em><span>QUEEN OR KING<\/span><\/div><\/div><div style=\"display:grid;gap:4px;justify-items:center\"><div class=\"sc up s\"><i>ESCAPE PLAN<\/i><b>A, J<\/b><em>MATCH<\/em><span>ACE OR JACK<\/span><u class=\"hard\">HARD<\/u><\/div><div class=\"sc pat hard s\"><i>GUARD CHECK<\/i><b>RELAXED<\/b><em>DO NOT MATCH<\/em><span>ACE OR JACK<\/span><\/div><\/div><div style=\"display:grid;gap:4px;justify-items:center\"><div class=\"sc up s\"><i>ESCAPE PLAN<\/i><b>8 OR 9<\/b><em>MATCH<\/em><span>8 OR 9<\/span><u class=\"hard\">HARD<\/u><\/div><div class=\"sc pat hard s\"><i>GUARD CHECK<\/i><b>RELAXED<\/b><em>DO NOT MATCH<\/em><span>8 OR 9<\/span><\/div><\/div><div style=\"display:grid;gap:4px;justify-items:center\"><div class=\"sc up s\"><i>ESCAPE PLAN<\/i><b>6 OR 7<\/b><em>MATCH<\/em><span>6 OR 7<\/span><u class=\"hard\">HARD<\/u><\/div><div class=\"sc pat hard s\"><i>GUARD CHECK<\/i><b>RELAXED<\/b><em>DO NOT MATCH<\/em><span>6 OR 7<\/span><\/div><\/div><div style=\"display:grid;gap:4px;justify-items:center\"><div class=\"sc up s\"><i>ESCAPE PLAN<\/i><b>4 OR 5<\/b><em>MATCH<\/em><span>4 OR 5<\/span><u class=\"hard\">HARD<\/u><\/div><div class=\"sc pat hard s\"><i>GUARD CHECK<\/i><b>RELAXED<\/b><em>DO NOT MATCH<\/em><span>4 OR 5<\/span><\/div><\/div><div style=\"display:grid;gap:4px;justify-items:center;align-self:center\"><div class=\"sc alarm s\"><i>ALARM SOUNDS<\/i><b>🚨<\/b><span>Drawing LOCKED. Pass allowed.<\/span><\/div><div class=\"lab\">Alarm Sounds<\/div><\/div><\/div><\/div>\n <div class=\"box\"><h3>Ranks<\/h3><p style=\"font-size:9.2pt\">Ace is low: A = 1, J = 11, Q = 12, K = 13. <b>ODD<\/b> = A, 3, 5, 7, 9, J, K. <b>EVEN<\/b> = 2, 4, 6, 8, 10, Q. <b>LOW<\/b> = A through 6. <b>HIGH<\/b> = 7 through K.<\/p><\/div>\n <div class=\"foot\"><span>Escape from Ace-catraz · Rules<\/span><span>6<\/span><\/div><\/div>";
